root=Path(__file__).resolve().parents[2];p=root/'research/nine-sharing-sign16-main-norm-check';draft=root/'research/nine-sharing-sign16-main-norm-draft';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest();run=p/'run.py';m=p/'source-manifest.json';assert sha(run)=='83af1da580085bc4b055befa8279b7f3018f6912c210f093918ccb0f7970e748' and sha(m)=='3a0b66290ac838f116e36bbcb30759289997d13d3fc453b633b3eda02ed1a766';row,=json.loads(m.read_text())['rows'];name='Sign16MainNorm';src=p/'src/DiophantineConsistency'/(name+'.lean');s=src.read_text();assert sha(src)==sha(draft/(name+'.lean'))==row['source_sha256'] and row['module']=='DiophantineConsistency.'+name and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==row['imports']==['DiophantineConsistency.Sign16OtherRows','DiophantineConsistency.Sign16MoreSharedValues'];assert not re.search(r'(?m)^\s*(axiom|opaque)\b|\b(sorry|admit)\b',s)
for t in ('theorem main_of_seed','(hp : ((p 0 : ℤ) : DiffRing V) = ι beta)','(hz : InternalZero (seed p) v)','d*d = 1 + ((a+1)*(a+3))*c*c','Sign16OtherRows.row00_of_seed','Sign16MoreSharedValues.root_delta_eval','Sign16MoreSharedValues.delta_eval','Sign16SharedValues.c_eval'):assert t in s
r=run.read_text();survey=p/'provider-survey.py';assert sha(survey)=='7a4410a3f6a0c3fc5e60010dc36fde180ddb2e13a5115133c9b3825b3c7993a1' and "if local=='Sign16MoreSharedValues':" in r and "for rel,rec in survey['extra'].items():" in r and "'-M2800'" in r and 'rss_limit=4*1024**3,mem_floor=10*1024**3,seconds=120,interval=.1' in r
for label,pin in [('other-rows','42ca8a3845f213546dae9ef997cd401de3bfce072176c9b639db4de04dd30bcb'),('more-shared-values','9249cd245922d9d101bbfc585e6efe52adb602fa9477e56dce2c129ab90a142d')]:
 check=root/('reviews/nine-sharing-sign16-'+label+'-terminal-independent/check.py');assert sha(check)==pin;subprocess.run([sys.executable,'-I','-S','-B',str(check)],capture_output=True,check=True,timeout=120)
z=subprocess.run([sys.executable,'-I','-S','-B',str(survey)],capture_output=True,text=True,check=True,timeout=120);surveydata=json.loads(z.stdout);assert surveydata['status']=='PASS' and len(surveydata['extra'])==1 and surveydata['object_sha256']=='5e42053df838402727f0c10b1f1fa59f0ed46e0c9cdbd676c71353ef044cd216'
x=subprocess.run([sys.executable,'-I','-S','-B',str(run),'--preflight'],capture_output=True,text=True,timeout=180);assert x.returncode==0 and not x.stderr and json.loads(x.stdout)['status']=='PASS_NO_LEAN_PREFLIGHT'
print(json.dumps({'status':'PASS_PRELAUNCH','runner_sha256':sha(run),'extra_overlays':1,'overlap':surveydata['overlap_count'],'scope':'conditional natural main norm from seed and represented beta; remaining norms and lift unproved'},indent=2,sort_keys=True))
